function active$Form&Controller;(f) {
  f.add_onResponseComplete(on$Form&Controller;$ResponseComplete);
  var g = f.grid, info = g._$dataGL, client = info.Client;
  setValueField$ByArrayValue(f, info, client[info.IndexActive]);
  f._$fieldType = getFieldByType(f._fields, 'list');

  var p = f.getItemValue('so_ky_pb');
  if (!f.getItemValue('ngay_pb_kt') && p != 0) increaseDays$AutoGenerate(f.$_method&Controller;, f.getItemValue('ngay_pb0'), p, f.getItem('ngay_pb_kt'));
  var v1 = (f.getItemValue('kieu_pb') == 0), v2 = (f.getItemValue('so_ky_pb') == 0);
  setItemAllowNulls(f, 'ngay_pb_kt', !v1);
  f.getItem('so_ky_pb').disabled = !v1;
}
function close$Form&Controller;(f) {
  try {f.remove_onResponseComplete(on$Form&Controller;$ResponseComplete)} catch (ex) {}
  window.setTimeout(function() {var g = f.grid;if (g._activeCell) g._activeCell.focus();else {var t1 = g._$parentForm._findButton('Ok');if (t1) {t1.focus();t1.live;}}}, 50);
}
function on$Form&Controller;$ResponseComplete(sender, e) {
  var f = e.object, context = e.type.Context, result = e.type.Result, g = f.grid;
  switch (context) {
    case 'Checking':
      objectBehavior$Dir$Irregular.checkCode(f, 'ma_cc');
      if !(f._checked) {break;}

      var info = g._$dataGL, client = info.Client;
      var value = getValueField$ByFields(f, info);
      var row = g._activeRow;
      info.Client[info.IndexActive] = value;
      g._setItemValue(row, g._getColumnOrder('ma_cc'), f.getItemValue('ma_cc').toUpperCase());
      g._setItemValue(row, g._getColumnOrder('ten_cc'), f.getItemValue('ten_cc'));
      f._checked = false;
      f.closeDialog();
      break;
    case 'TSCategoryCreateAuto':
      f.setItemControlBehavior('kieu_pb', result[0].Value, null, true);
      f.setItemValue('so_ky_pb', result[1].Value);
      f.setItemValue('ma_phi', result[2].Value);
      f.setItemControlBehavior('loai_dc', result[3].Value, result[4].Value, true);
      f.setItemControlBehavior('ma_ld_tg', result[5].Value, result[6].Value, true);
      f.setItemControlBehavior('tk_dc', result[7].Value, result[8].Value, true);
      f.setItemControlBehavior('tk_pb', result[9].Value, result[10].Value, true);

      onChange$&Controller;$AllocationMethod(f.getItem('kieu_pb'))
      onChange$&Controller;$AllocationPeriods(f.getItem('so_ky_pb'));
      break;
    default:
      break;
  }
}

function onChange$&Controller;$AllocationMethod(o) {
  var f = o.parentForm, k = f.getItem('so_ky_pb'), d = f.getItem('ngay_pb_kt'), v = (f.getItemValue('kieu_pb') == 0);
  setItemAllowNulls(f, 'ngay_pb_kt', !v);
  window.setTimeout(String.format('onFocus$&Controller;$AllocationMethod(\'{0}\', \'{1}\', \'{2}\', \'{3}\', {4});', f._id, o.id, k.id, d.id, v ? 1 : 0), 2);
}
function onFocus$&Controller;$AllocationMethod(c1, c2, c3, c4, v) {
  var f = $find(c1), o = $get(c2), k = $get(c3), d = $get(c4);
  setItemLive(k, d, v);
  setItemDisable(f, 'so_ky_pb', !v);
  on$&Controller;$AllocationType$Change(f);
}
function on$&Controller;$AllocationType$Change(f) {
  var v = (f.getItemValue('kieu_pb') != 0);
  if (v) {
    f.setItemValue('so_ky_pb', 2);
    onChange$&Controller;$AllocationPeriods(f.getItem('so_ky_pb'));
  } else increaseDays$AutoGenerate(f.$_method&Controller;, f.getItemValue('ngay_pb0'), f.getItemValue('so_ky_pb'), f.getItem('ngay_pb_kt'));
  setItemAllowNulls(f, 'ngay_pb_kt', v);
}

function onChange$&Controller;$AllocationPeriods(o) {
  var f = o.parentForm, d = f.getItem('ngay_pb_kt');
  f.executeExpression(['[gt_pb_ky_nt]:=[so_ky_pb] == 0 ? 0 : [nguyen_gia_nt]/[so_ky_pb]']);
  f.executeExpression(['[gt_pb_ky]:=[so_ky_pb] == 0 ? 0 : [nguyen_gia]/[so_ky_pb]']);
  f.executeExpression(['[gt_cl_nt]:=[nguyen_gia_nt]']);
  f.executeExpression(['[gt_cl]:=[nguyen_gia]']);

  if (o.value != 0) if (o.value != 0) increaseDays$AutoGenerate(f.$_method&Controller;, f.getItemValue('ngay_pb0'), f.getItemValue('so_ky_pb'), d);
    else f.setItemValue('ngay_pb_kt', null);
  f.live(f.getItem('ngay_pb_kt'));
}
function onChange$&Controller;$OriginalCostFC(o) {
  var f = o.parentForm;
  f.executeExpression(['[gt_cl_nt]:=[nguyen_gia_nt]']);
  f.executeExpression(['[gt_pb_ky_nt]:=[so_ky_pb] == 0 ? 0 : [nguyen_gia_nt]/[so_ky_pb]']);
}
function onChange$&Controller;$OriginalCost(o) {
  var f = o.parentForm;
  f.executeExpression(['[gt_cl]:=[nguyen_gia]']);
  f.executeExpression(['[gt_pb_ky]:=[so_ky_pb] == 0 ? 0 : [nguyen_gia]/[so_ky_pb]']);
}
function onChange$&Controller;$TSCategoryCreateAuto(o) {
  var f = o.parentForm;
  f.request('TSCategoryCreateAuto', 'TSCategoryCreateAuto', ['ma_pl_cc'], o);
}
function onChange&Controller;$Currency(f) {
  var v = (f._baseCurrency&Controller;.toUpperCase() == f.getItemValue('ma_nt').toUpperCase());
  var a = ['nguyen_gia, gt_pb_ky', 'nguyen_gia_nt, gt_pb_ky_nt'];
  var b = a[0].split(','), c = a[1].split(',');
  for (var i = 0; i < b.length; i++) {
    var n1 = $func.trim(b[i]), n2 = $func.trim(c[i]);
    var c1 = $get('idf_' + n1), c2 = $get('idf_' + n2), t1 = f.getItem(n1), t2 = f.getItem(n2);
    var format, h = t2._controlBehavior, changed = v;

    if (v) {
      if (!t2._saveDataFormatString) t2._saveDataFormatString = t2.field.DataFormatString;
      format = t1.field.DataFormatString;
    else {
      format = t2.field.DataFormatString;
      changed = true;
    }
    if (changed) {
      t2.field.DataFormatString = format;
      h.set_format(format);
      var n = $func.scaleLength(format);
      h._set_number($func.round(h._get_number(), n));
      $common.setVisible(t1.parentNode, !v);
    }
  }
}
function setItemLive(t1, t2, type) {
  var f = t1.parentForm;
  if (type) {if (t2.live) {t1.disabled = false; t1.focus();f.live(t1);}}
    else {if (t1.live) {t2.disabled = false; t2.focus();f.live(t2);}}
}
function setItemDisable(f, c, v) {
  var a = c.split(',');
  for (var i = 0; i < a.length; i++) {
    var o = f.getItem($func.trim(a[i]));
    if (o.a) $common.setVisible(o.a, !v);
    o.disabled = v;
  }
}
function setItemAllowNulls(f, c, v) {
  var a = c.split(','), o, grandNode;
  for (var i = 0; i < a.length; i++) {
    if ($func.trim(a[i]) != '') {
      o = f.getItem($func.trim(a[i]));
      o.field.AllowNulls = !v
      grandNode = o.parentNode.parentNode;
      if (v) {
        Sys.UI.DomElement.addCssClass(grandNode, 'Required');
        Sys.UI.DomElement.addCssClass(grandNode, f._id);
      }
      else Sys.UI.DomElement.removeCssClass(grandNode, 'Required');
    }
  }
}

      &ScriptIrregular;
